INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers") VALUES (4600991101010113, ARRAY['"What does the term Purusharthas denote in the syllabus?"'::jsonb, '"Which Ashrama is conventionally associated with household responsibilities?"'::jsonb, '"Which craft technology is specifically included with ancient Indian specialities?"'::jsonb, '"Which is a core mathematical topic explicitly listed in the BKS syllabus?"'::jsonb, '"Which is the best description of an Itihasa text in this syllabus?"'::jsonb, '"Which is one of the four Purusharthas?"'::jsonb, '"Which option best describes Bharatiya Knowledge Systems (BKS) in the course context?"'::jsonb, '"Which pair is conventionally treated as Itihasa in the course context?"'::jsonb, '"Which Ashrama is commonly associated with retirement from household life and gradual withdrawal?"'::jsonb, '"How many Vedas are introduced in the course?"'::jsonb, '"Which list gives the four Purusharthas?"'::jsonb, '"Which Purushartha is most closely related to material prosperity or means?"'::jsonb, '"Which Vedanga primarily concerns pronunciation and phonetics?"'::jsonb, '"Which of the following is a technology-and-environment theme in the syllabus?"'::jsonb, '"Which Vedanga concerns metre in verse?"'::jsonb, '"Which syllabus topic considers methods of measuring time and calendars?"'::jsonb, '"Which example best represents water management as a technology topic?"'::jsonb, '"Which Ashrama follows Grihastha in the conventional four-stage sequence?"'::jsonb, '"Which term means the duty/ethical order dimension among the Purusharthas?"'::jsonb, '"Which Vedanga explains words through etymology and meanings?"'::jsonb, '"Which term is associated with renunciation in the four-Ashrama model?"'::jsonb, '"Which Vedanga relates to ritual procedures?"'::jsonb, '"Which Vedanga is associated with grammar?"'::jsonb, '"Which pair combines a Vedanga and its focus correctly?"'::jsonb, '"Which Veda is strongly associated with chants and musi